This Terraform configuration creates a basic AWS Lex V1 bot using `aws_lex_bot`. It also defines a simple Lex intent that the bot can recognize. The bot uses a clarification prompt, an abort statement, and returns the matched intent to the client for fulfillment.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Lex bot will be created."
  type        = string
  default     = "us-east-1"
}

variable "lex_bot_name" {
  description = "Name of the AWS Lex bot."
  type        = string
  default     = "SampleTerraformLexBot"
}

variable "lex_intent_name" {
  description = "Name of the AWS Lex intent."
  type        = string
  default     = "SampleGreetingIntent"
}

resource "aws_lex_intent" "greeting_intent" {
  name        = var.lex_intent_name
